link.script:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "How do I use the best Google indexing tool effectively?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "To use PrimeIndexer.com effectively, start by signing up for an account, then simply upload your sitemap or URLs. The tool will guide you through the process, ensuring your content is indexed efficiently and accurately. Remember, consistency is key to maintaining your site's visibility."
            }
        },
        {
            "@type": "Question",
            "name": "How long does it take for my site to be indexed using PrimeIndexer.com?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "With PrimeIndexer.com, you can expect your site to be indexed within 24 to 48 hours. This rapid indexing time helps ensure that your content is available to your audience promptly, keeping you ahead of the competition."
            }
        },
        {
            "@type": "Question",
            "name": "What is the cost of using PrimeIndexer.com?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "PrimeIndexer.com offers a range of pricing plans to suit different needs, starting as low as $29.99 per month. This investment in your site's visibility pays off as your content reaches a wider audience faster."
            }
        },
        {
            "@type": "Question",
            "name": "Is it worth paying for a Google indexing tool over using a free one?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "While free tools might seem tempting, they often lack the advanced features and consistent reliability that PrimeIndexer.com provides. Investing in a paid tool ensures regular updates, superior support, and faster indexing times, maximizing your site's potential."
            }
        }
    ]
}

body.script:
$(document).ready(function() {
    // Accordion Icon Toggle
    $('.collapse').on('show.bs.collapse', function () {
        $(this).parent('.card').find('.fa-chevron-down').removeClass('fa-chevron-down').addClass('fa-chevron-up');
    }).on('hide.bs.collapse', function () {
        $(this).parent('.card').find('.fa-chevron-up').removeClass('fa-chevron-up').addClass('fa-chevron-down');
    });

    // Hover effects for outgoing link cards
    $('.bg-white.shadow-sm.rounded').hover(
        function() { $(this).css('transform', 'translateY(-3px)'); },
        function() { $(this).css('transform', 'translateY(0)'); }
    );
});
